css:
body :where([data-bz-node="why"]) .bz-block{padding:0}
body :where([data-bz-node="why"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="why"]>.bz-container{padding-inline:0}

body [data-bz-node="why"]{background:#fff;padding:100px 0 101px}
body [data-bz-node="why"]>.bz-container{max-width:var(--container)}
body [data-bz-node="why-head"] .bz-headingblock{text-align:center}
body [data-bz-node="why-head"] .bz-eyebrow{font:700 11px/1.4 var(--font-body);letter-spacing:.2em;text-transform:uppercase;color:#6b6b6a;margin:0 0 6px;margin-bottom:8px}
body [data-bz-node="why-head"] h2{font:700 42.4px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0;font-size:42.4px}
body [data-bz-node="why-grid"]{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin:38px 1px 0}
body [data-bz-node^="why-card-"]{grid-column:auto;display:flex;flex-direction:column;align-items:center;text-align:center;border:1px solid #d4d4d2;background:#fff;padding:30px 12px 0;height:176px;box-sizing:border-box}
body [data-bz-node^="why-icon-"]{width:46px;height:46px;border:1px solid var(--ink);border-radius:50%;display:flex;align-items:center;justify-content:center;margin-bottom:13px;flex:0 0 auto}
body [data-bz-node^="why-icon-"] .bz-container,body [data-bz-node^="why-icon-"] figure{display:contents}
body [data-bz-node^="why-icon-"] img{width:26px;height:26px}
body [data-bz-node^="why-value-"] h3{font:700 30px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;margin:0;color:var(--ink)}
body [data-bz-node^="why-label-"] p{font:400 12.5px/1.4 var(--font-body);letter-spacing:0;color:#333;margin:7px 0 0}
@media (max-width:1100px){
  body [data-bz-node="why"]{padding:72px 24px}
  body [data-bz-node="why-head"] h2{font-size:34px}
  body [data-bz-node="why-grid"]{grid-template-columns:repeat(3,1fr);margin-top:40px}
}
@media (max-width:640px){
  body [data-bz-node="why"]{padding:56px 20px}
  body [data-bz-node="why-head"] h2{font-size:28px}
  body [data-bz-node="why-grid"]{grid-template-columns:repeat(2,1fr);gap:12px}
  body [data-bz-node^="why-card-"]{padding:24px 8px 0}
  body [data-bz-node^="why-card-"]:last-child:nth-child(odd){grid-column:1/-1}
}
